from typing import Dict, List, Optional


class Bot:
    """A bot sees each user message in a channel and may return one reply line."""
    name = "Bot"

    def reply(self, channel: "Channel", user: str, text: str) -> Optional[str]:
        return None


class EchoBot(Bot):
    name = "EchoBot"

    def reply(self, channel, user, text):
        return f"{self.name}: {text}"


class HelpBot(Bot):
    name = "HelpBot"

    def reply(self, channel, user, text):
        return f"{self.name}: available commands: help" if text == "help" else None


# New bot types only need to be added here; the chat core never changes.
BOT_TYPES: Dict[str, type] = {cls.name: cls for cls in (EchoBot, HelpBot)}


class Channel:
    def __init__(self) -> None:
        self.history: List[str] = []
        self.state: Dict[str, dict] = {}     # per-bot state scoped to this channel


def runChatAppCommands(commands: List[str]) -> List[str]:
    channels: Dict[str, Channel] = {}
    bots: List[Bot] = []
    registered = set()
    out: List[str] = []
    for cmd in commands:
        parts = cmd.split()
        if not parts:
            continue
        op = parts[0]
        if op == "REGISTER":
            for name in parts[1:]:
                if name in BOT_TYPES and name not in registered:   # unknown or duplicate: ignore
                    registered.add(name)
                    bots.append(BOT_TYPES[name]())
        elif op == "SEND":
            ch = channels.setdefault(parts[1], Channel())
            user, text = parts[2], " ".join(parts[3:])
            ch.history.append(f"{user}: {text}")
            for bot in bots:                      # replies in registration order
                r = bot.reply(ch, user, text)
                if r is not None:
                    ch.history.append(r)
        elif op == "PRINT":
            ch = channels.get(parts[1])
            if ch:
                out.extend(ch.history)
    return out


if __name__ == "__main__":
    res = runChatAppCommands([
        "SEND c1 alice hi",
        "REGISTER EchoBot HelpBot EchoBot",
        "SEND c1 bob help",
        "SEND c2 carol hello there",
        "PRINT c1",
        "PRINT c2",
        "PRINT c3",
    ])
    assert res == [
        "alice: hi",
        "bob: help", "EchoBot: help", "HelpBot: available commands: help",
        "carol: hello there", "EchoBot: hello there",
    ], res
    print("ok")
